// fix-health-app.cjs — Family Health Track v2.4.6 one-step fix
// Run from the project root (the folder with package.json) with:
//   node fix-health-app.cjs
// What it does:
//   1. Backs up each changed file to <file>.bak (first run only)
//   2. Applies the v2.4.6 fixes (dual-key data visibility, Emergency ID,
//      fabricated defaults, Data Repair panel, version history)
//   3. Runs npm install, typecheck (tsc), tests (vitest) and build
//   4. Only after all checks pass, deletes the old hand-fix scripts
// Safe to run twice: files already matching the new content are skipped.
// It does NOT touch your data, your Firebase project, or git.
// ---------------------------------------------------------------------------
// IMPORTANT — do this in the Firebase Console BEFORE relying on the app:
//   The zip that was shared contained serviceAccountKey.json (a live admin
//   credential). If that file is still on your machine, revoke/rotate the
//   key in Firebase Console > Project Settings > Service accounts, then
//   delete the file. This script only warns about it; it cannot revoke it.
// ---------------------------------------------------------------------------
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const VERSION = '2.4.6';
const FILES = [
  {
    "path": "package.json",
    "b64": ""
  },
  {
    "path": "src/components/charts/HealthCharts.tsx",
    "b64": ""
  },
  {
    "path": "src/components/layout/Sidebar.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/AdminPatientPortal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/BMIModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/BloodSugarModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/DataBackupModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/EmergencyIDModule.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/TrendsOverview.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/VersionHistoryModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminAddPatientModal.tsx",
    "b64": ""
  },
  {
    "path": "src/components/modules/admin/AdminDataRepair.tsx",
    "b64": ""
  },
  {
    "path": "src/constants/version.ts",
    "b64": "ZXhwb3J0IGNvbnN0IENVUlJFTlRfU1lTVEVNX1ZFUlNJT04gPSAndjIuNC42JzsK"
  },
  {
    "path": "src/context/HealthDataContext.tsx",
    "b64": ""
  },
  {
    "path": "src/types/health.ts",
    "b64": ""
  }
];
const DELETE_AFTER_SUCCESS = [
  "fix_data.mjs",
  "fix_every_user.mjs",
  "fix_bmi_userid.mjs",
  "fix_old_uid.mjs",
  "inspect_data.mjs",
  "inspect_all_data.mjs",
  "dump_all_documents.mjs",
  "fix_final_auth_and_cleanup.cjs",
  "migrate_data_browser.html"
];

const norm = (s) => String(s).replace(/\r\n/g, '\n');
let applied = 0, skipped = 0, failed = 0;
const failures = [];

function run(cmd, args, label) {
  console.log('  $ ' + cmd + ' ' + args.join(' '));
  const r = spawnSync(cmd, args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.error || r.status !== 0) {
    console.log('[FAIL] ' + label + ' (exit ' + (r.status ?? r.error) + ')');
    return false;
  }
  console.log('[OK] ' + label);
  return true;
}

function main() {
  console.log('Family Health Track fix — v' + VERSION);
  console.log('Project folder: ' + process.cwd());
  const pkgPath = path.join(process.cwd(), 'package.json');
  if (!fs.existsSync(pkgPath)) {
    console.log('[ERROR] package.json not found here. Run this script from the project root (the folder with package.json).');
    process.exit(1);
  }
  let pkg;
  try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch (e) {
    console.log('[ERROR] package.json could not be read: ' + e.message);
    process.exit(1);
  }
  if (pkg.name !== 'family-health-track') {
    console.log('[ERROR] This does not look like the Family Health Track project (package name: ' + pkg.name + '). Stopping.');
    process.exit(1);
  }
  if (!['2.4.3', '2.4.5', '2.4.6'].includes(String(pkg.version))) {
    console.log('[ERROR] Unexpected project version ' + pkg.version + ' (expected 2.4.3 or 2.4.5). Stopping — ask for help before running this.');
    process.exit(1);
  }
  if (fs.existsSync(path.join(process.cwd(), 'serviceAccountKey.json'))) {
    console.log('');
    console.log('!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!');
    console.log('WARNING: serviceAccountKey.json is still in this folder.');
    console.log('It is a live Firebase admin credential. Revoke/rotate it in');
    console.log('Firebase Console > Project Settings > Service accounts, then');
    console.log('delete the file. The fix below does not need it.');
    console.log('!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!');
    console.log('');
  }

  for (const f of FILES) {
    const dest = path.join(process.cwd(), ...f.path.split('/'));
    const next = Buffer.from(f.b64, 'base64').toString('utf8');
    try {
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      if (fs.existsSync(dest) && norm(fs.readFileSync(dest, 'utf8')) === norm(next)) {
        console.log('[SKIP] already applied: ' + f.path);
        skipped++;
        continue;
      }
      if (fs.existsSync(dest) && !fs.existsSync(dest + '.bak')) {
        fs.copyFileSync(dest, dest + '.bak');
      }
      fs.writeFileSync(dest, next, 'utf8');
      console.log('[OK] applied: ' + f.path);
      applied++;
    } catch (e) {
      console.log('[FAIL] ' + f.path + ': ' + e.message);
      failed++;
      failures.push(f.path + ': ' + e.message);
    }
  }
  console.log('');
  console.log('Applied ' + applied + ' | Already applied ' + skipped + ' | Failed ' + failed);
  if (failed > 0) {
    console.log('Failures: ' + failures.join(' ; '));
    console.log('Stopping before checks. Your .bak backups are next to the originals.');
    process.exit(1);
  }

  console.log('');
  console.log('--- checks (npm install, typecheck, tests, build) ---');
  const okInstall = run('npm', ['install', '--no-audit', '--no-fund'], 'npm install');
  const okLint = run('npx', ['tsc', '--noEmit'], 'typecheck (tsc --noEmit)');
  const okTest = run('npx', ['vitest', 'run'], 'tests (vitest run)');
  const okBuild = run('npm', ['run', 'build'], 'build (vite build)');
  if (!okInstall || !okLint || !okTest || !okBuild) {
    console.log('');
    console.log('[DONE WITH ERRORS] Files were updated, but a check failed above.');
    console.log('Do NOT deploy yet. Ask for help and include the error lines above.');
    process.exit(1);
  }

  console.log('');
  console.log('--- cleanup: deleting old hand-fix scripts (replaced by Data Repair) ---');
  for (const rel of DELETE_AFTER_SUCCESS) {
    const p = path.join(process.cwd(), rel);
    try {
      if (fs.existsSync(p)) { fs.unlinkSync(p); console.log('[DEL] ' + rel); }
    } catch (e) { console.log('[WARN] could not delete ' + rel + ': ' + e.message); }
  }

  console.log('');
  console.log('[DONE] v' + VERSION + ' applied. Applied ' + applied + ' | Already applied ' + skipped + ' | Failed 0');
  console.log('');
  console.log('NEXT STEPS (do these in order):');
  console.log('  1. In the Firebase Console, revoke the old service-account key');
  console.log('     (Project Settings > Service accounts) if you have not yet,');
  console.log('     and delete serviceAccountKey.json from this folder.');
  console.log('  2. Deploy / push the app (git push, then your host redeploys).');
  console.log('  3. Open the live app as ADMIN, go to Admin portal, click');
  console.log("     'Data Repair' > 'Check and fix' ONCE, and note the counts.");
  console.log('  4. Log in as a test patient and check that records the admin');
  console.log('     entered for them now appear. Version History must show v2.4.6.');
}

main();
